package cc.huevia.album;

import cc.huevia.ncp.*;
import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

public final class PhotoColorAdjustmentsTest {
    private static int checks;
    public static void main(String[] args)throws Exception{
        for(int c=0;c<4;c++)for(int x=0;x<256;x++)check(Math.abs(PhotoCurves.NONE.map(c,x/255.0)*255-x)<1e-9,"neutral curve is exact");
        PhotoCurves lifted=PhotoCurves.NONE.withPoints(0,new int[]{0,0,64,85,128,170,192,222,255,255});
        double previous=-1;for(int i=0;i<2550;i++){double value=lifted.map(0,i/2549.0);check(value>=previous-1e-12&&value>=0&&value<=1,"monotone curve has no overshoot");previous=value;}
        int[] immutable=lifted.points(0);immutable[1]=200;check(lifted.points(0)[1]==0,"curve points immutable");
        expect(()->PhotoCurves.NONE.withPoints(0,new int[]{0,0,128,180,127,200,255,255}));expect(()->PhotoCurves.NONE.withPoints(0,new int[]{1,0,255,255}));expect(()->PhotoCurves.NONE.withPoints(4,new int[]{0,0,255,255}));
        PhotoCurves red=PhotoCurves.NONE.withPoints(1,new int[]{0,0,128,180,255,255});PhotoAdjustments curve=PhotoAdjustments.NONE.withCurves(red);int value=AdjustedPreviewProfile.of(null,curve).applyArgb(0xa5808080);check((value>>>24)==0xa5&&((value>>>16)&255)>128&&((value>>>8)&255)==128&&(value&255)==128,"red curve changes red only, preserves alpha");
        PhotoHsl hsl=PhotoHsl.NONE.with(0,1,-100);PhotoAdjustments mix=curve.withHsl(hsl);PresetPreviewProfile selective=AdjustedPreviewProfile.of(null,PhotoAdjustments.NONE.withHsl(hsl));
        check(selective.applyArgb(0xfff02020)!=0xfff02020,"red saturation changes red");check(selective.applyArgb(0xff2030e0)==0xff2030e0,"red saturation preserves blue");check(selective.applyArgb(0xff808080)==0xff808080,"HSL preserves gray");check(selective.applyArgb(0xff000000)==0xff000000&&selective.applyArgb(0xffffffff)==0xffffffff,"HSL preserves black/white");
        PhotoHsl orange=PhotoHsl.NONE.with(1,0,60).with(1,1,30).with(1,2,40);double[] a={1,.49,0},b={1,.51,0};orange.apply(a);orange.apply(b);check(Math.abs(a[0]-b[0])+Math.abs(a[1]-b[1])+Math.abs(a[2]-b[2])<.12,"smooth HSL band transitions");
        expect(()->PhotoHsl.NONE.with(8,0,0));expect(()->PhotoHsl.NONE.with(0,0,101));
        check(mix.with(PhotoAdjustments.Parameter.EXPOSURE,5).curves.equals(red)&&mix.with(PhotoAdjustments.Parameter.EXPOSURE,5).hsl.equals(hsl),"basic edits preserve advanced settings");
        check(!mix.identity().equals(curve.identity())&&!mix.identity().equals(PhotoAdjustments.NONE.identity()),"all advanced values affect identity");
        check(profileKey(mix).length()<100&&!profileKey(mix).equals(profileKey(curve)),"advanced model key is bounded and value-sensitive");
        PhotoEditStore.Draft maxIdentity=new PhotoEditStore.Draft("f".repeat(64),NcpCompatibilityFixtures.ncp(),"Identity",99,mix,PhotoGeometry.NONE.rotate().straighten(31),PhotoBorder.NONE.withTemplate(3),false);check((maxIdentity.profile().modelVersion()+":full-jpeg95-srgb-v1").length()<=256,"advanced plus preset geometry border fits export model ledger");
        PhotoAdjustments selectiveCopy=PhotoAdjustments.NONE.with(PhotoAdjustments.Parameter.EXPOSURE,8).copyFrom(mix,false,true,false);check(selectiveCopy.get(PhotoAdjustments.Parameter.EXPOSURE)==8&&selectiveCopy.curves.equals(red)&&selectiveCopy.hsl.isNeutral(),"copy scope preserves unselected categories");
        int[] pixels=new int[4096];Random random=new Random(106);for(int i=0;i<pixels.length;i++)pixels[i]=random.nextInt();int[] snapshot=pixels.clone();PresetPreviewProfile profile=AdjustedPreviewProfile.of(null,mix);int[] rendered=profile.render(pixels,64,64);for(int i=0;i<pixels.length;i++){check(rendered[i]==profile.applyArgb(pixels[i]),"single pixel and complete colour render match");check((rendered[i]>>>24)==(pixels[i]>>>24),"render alpha unchanged");}check(Arrays.equals(pixels,snapshot),"source pixels untouched");
        File root=Files.createTempDirectory("colour-106-").toFile();String sha="a".repeat(64);PhotoEditStore store=new PhotoEditStore(root,"owner");PhotoEditStore.Draft draft=new PhotoEditStore.Draft(sha,NcpCompatibilityFixtures.ncp(),"Fixture",70,mix,PhotoGeometry.NONE.rotate(),PhotoBorder.NONE,false);store.save(draft);check(store.read(sha).adjustments.equals(mix)&&store.read(sha).identity().equals(draft.identity()),"PED5 roundtrip curves/HSL");
        PhotoRecipeStore recipes=new PhotoRecipeStore(root,"owner");PhotoRecipeStore.Recipe recipe=recipes.create("Color",draft);check(recipes.read(recipe.id).adjustments.equals(mix),"PRC2 roundtrip curves/HSL");
        PhotoRecipeStore.Recipe oldRecipe=recipes.create("Legacy",new PhotoEditStore.Draft("e".repeat(64),null,"",0,PhotoAdjustments.NONE,false));File oldRecipeFile=new File(root,"photo-recipes/"+PhotoEditStore.hash("owner".getBytes(java.nio.charset.StandardCharsets.UTF_8))+"/"+oldRecipe.id+".recipe");ByteArrayOutputStream oldBytes=new ByteArrayOutputStream();try(DataOutputStream out=new DataOutputStream(oldBytes)){out.writeInt(0x50524331);out.writeUTF(oldRecipe.id);out.writeUTF(oldRecipe.name);out.writeLong(oldRecipe.createdAt);out.writeUTF("无滤镜");out.writeInt(0);out.writeInt(0);out.writeUTF(PhotoAdjustments.MODEL);out.writeInt(13);for(int i=0;i<13;i++)out.writeInt(0);}try(FileOutputStream out=new FileOutputStream(oldRecipeFile)){byte[] body=oldBytes.toByteArray();out.write(body);out.write(MessageDigest.getInstance("SHA-256").digest(body));}check(recipes.read(oldRecipe.id).adjustments.isNeutral(),"PRC1 recipe migrates with neutral curves and HSL");
        String legacySha="b".repeat(64);writeLegacy(root,"owner",legacySha,0x50454434);PhotoEditStore.Draft legacy=store.read(legacySha);check(legacy.adjustments.isNeutral()&&legacy.geometry.isNeutral()&&legacy.border.isNone(),"PED4 migrates to neutral advanced controls");
        PhotoEditStore.Draft targetA=new PhotoEditStore.Draft("c".repeat(64),NcpCompatibilityFixtures.ncp(),"Target",43,PhotoAdjustments.NONE,PhotoGeometry.NONE.rotate(),PhotoBorder.NONE.withTemplate(1),false);
        store.save(targetA);String absent="d".repeat(64);List<PhotoAdjustmentCopy.Target> targets=Arrays.asList(new PhotoAdjustmentCopy.Target(targetA.sourceSha,targetA,targetA),new PhotoAdjustmentCopy.Target(absent,null,null));
        PhotoAdjustmentCopy.Receipt copied=PhotoAdjustmentCopy.apply(store,targets,mix,true,true,true,()->true);check(copied.changed()==2,"copy writes all prepared targets");PhotoEditStore.Draft result=store.read(targetA.sourceSha);check(result.adjustments.equals(mix)&&result.geometry.equals(targetA.geometry)&&result.border.equals(targetA.border)&&result.strength==43&&result.presetSha.equals(targetA.presetSha),"copy preserves filter geometry border");
        check(copied.undo(store)==2&&store.read(absent)==null&&store.read(targetA.sourceSha).identity().equals(targetA.identity()),"undo restores previous draft or exact absence");
        copied=PhotoAdjustmentCopy.apply(store,targets,mix,true,true,true,()->true);PhotoEditStore.Draft newer=new PhotoEditStore.Draft(absent,null,"",0,mix.with(PhotoAdjustments.Parameter.EXPOSURE,2),false);store.save(newer);check(copied.undo(store)==1&&store.read(absent).identity().equals(newer.identity()),"undo never overwrites later independent edit");
        store.replace(absent,newer,null);AtomicInteger calls=new AtomicInteger();try{PhotoAdjustmentCopy.apply(store,targets,mix,true,true,true,()->calls.incrementAndGet()<3);throw new AssertionError("account change accepted");}catch(IOException expected){check(store.read(targetA.sourceSha).identity().equals(targetA.identity())&&store.read(absent)==null,"account change rolls back earlier copy writes");}
        PhotoEditStore.Draft conflict=new PhotoEditStore.Draft(targetA.sourceSha,null,"",0,PhotoAdjustments.NONE.with(PhotoAdjustments.Parameter.EXPOSURE,3),false);store.save(conflict);try{PhotoAdjustmentCopy.apply(store,targets,mix,true,true,true,()->true);throw new AssertionError("stale draft overwritten");}catch(IOException expected){check(store.read(targetA.sourceSha).identity().equals(conflict.identity())&&store.read(absent)==null,"stale preflight cannot overwrite newer draft");}
        check(new PhotoEditStore(root,"different-owner").read(sha)==null,"account draft isolation");
        PhotoAdjustments neutralPoints=PhotoAdjustments.NONE.withCurves(PhotoCurves.NONE.withPoints(0,new int[]{0,0,128,128,255,255}));PhotoEditStore.Draft neutralA=new PhotoEditStore.Draft(absent,null,"",0,PhotoAdjustments.NONE,false),neutralB=new PhotoEditStore.Draft(absent,null,"",0,neutralPoints,false);store.save(neutralB);check(neutralA.identity().equals(neutralB.identity())&&!store.replace(absent,neutralA,null),"CAS preserves later neutral control-point metadata despite equal pixel identity");
        System.out.println("PASS: "+checks+" curves/HSL pixels, migration, copy and conflict checks");
    }
    private static void writeLegacy(File root,String owner,String sha,int magic)throws Exception{File file=new File(root,"photo-edit-drafts/"+PhotoEditStore.hash(owner.getBytes(java.nio.charset.StandardCharsets.UTF_8))+"/"+sha+".draft");ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(DataOutputStream out=new DataOutputStream(bytes)){out.writeInt(magic);out.writeUTF(sha);out.writeUTF("无滤镜");out.writeInt(0);out.writeBoolean(false);out.writeInt(0);out.writeUTF(PhotoAdjustments.MODEL);out.writeInt(13);for(int i=0;i<13;i++)out.writeInt(0);out.writeUTF(PhotoGeometry.MODEL);out.writeInt(0);out.writeInt(0);out.writeInt(0);out.writeInt(0);out.writeInt(PhotoGeometry.UNIT);out.writeInt(PhotoGeometry.UNIT);PhotoBorder.NONE.write(out);}try(FileOutputStream out=new FileOutputStream(file)){byte[] body=bytes.toByteArray();out.write(body);out.write(MessageDigest.getInstance("SHA-256").digest(body));}}
    private static void expect(Runnable work){try{work.run();throw new AssertionError("invalid accepted");}catch(IllegalArgumentException e){checks++;}}
    private static String profileKey(PhotoAdjustments settings){return AdjustedPreviewProfile.of(null,settings).modelVersion();}
    private static void check(boolean value,String message){if(!value)throw new AssertionError(message);checks++;}
}
